// package.json
var productName = "JustDo";
var author = {
  name: "JustDo",
  email: "liangxhao@example.com"
};

// src/shared/productMetadata.ts
var ENGLISH_PRODUCT_NAME = /^[A-Za-z]{1,64}$/;
var WINDOWS_RESERVED_FILE_NAME = /^(con|prn|aux|nul)$/i;
var validateProductName = (value) => {
  if (!ENGLISH_PRODUCT_NAME.test(value) || WINDOWS_RESERVED_FILE_NAME.test(value)) {
    throw new Error(
      "package.json productName must be a non-reserved English word containing 1-64 ASCII letters only."
    );
  }
  return value;
};
var PRODUCT_NAME = validateProductName(productName);
var AUTHOR_NAME = author.name;
var PRODUCT_NAME_LOWERCASE = PRODUCT_NAME.toLocaleLowerCase("en-US");

