    "pluginOperationFailureGuidance.package": "\u8BF7\u70B9\u51FB\u201C\u590D\u5236\u9519\u8BEF\u8BE6\u60C5\u201D\uFF0C\u8054\u7CFB\u63D2\u4EF6\u63D0\u4F9B\u65B9\u6838\u5BF9\u683C\u5F0F\u3001\u5B89\u5168\u6821\u9A8C\u6216\u517C\u5BB9\u6027\uFF0C\u5E76\u53D6\u5F97\u4FEE\u6B63\u540E\u7684\u5B89\u88C5\u5305\u3002",
