    "pluginOperationFailureGuidance.enable": "\u5148\u67E5\u770B\u63D2\u4EF6\u8BE6\u60C5\u4E2D\u7684\u4F9D\u8D56\u8BF4\u660E\uFF1B\u5982\u63D0\u4F9B\u53EF\u7F16\u8F91\u7684\u914D\u7F6E\u5165\u53E3\uFF0C\u6309\u4E0A\u65B9\u539F\u56E0\u4FEE\u6B63\u914D\u7F6E\u3002\u6838\u5BF9\u63D2\u4EF6\u4ECD\u672A\u542F\u7528\u540E\uFF0C\u518D\u624B\u52A8\u542F\u7528\uFF1B\u65E0\u9700\u91CD\u65B0\u5B89\u88C5\u3002",
    "pluginOperationFailureGuidance.configuration": "\u8BF7\u6309\u4E0A\u65B9\u539F\u56E0\u68C0\u67E5\u914D\u7F6E\u3002\u5982\u63D2\u4EF6\u8BE6\u60C5\u63D0\u4F9B\u53EF\u7F16\u8F91\u5165\u53E3\uFF0C\u4FEE\u6B63\u540E\u4FDD\u5B58\uFF1B\u6CA1\u6709\u5165\u53E3\u6216\u4ECD\u5931\u8D25\u65F6\uFF0C\u590D\u5236\u9519\u8BEF\u8BE6\u60C5\u8054\u7CFB\u7BA1\u7406\u5458\u6216\u63D2\u4EF6\u63D0\u4F9B\u65B9\u3002",
    "pluginOperationFailureGuidance.runtime": "\u5173\u95ED\u63D0\u793A\u540E\uFF0C\u67E5\u770B\u6807\u9898\u680F\uFF08\u6700\u5C0F\u5316\u3001\u6700\u5927\u5316\u6309\u94AE\u65C1\uFF09\u7684 AI \u5F15\u64CE\u72B6\u6001\u3002\u542F\u52A8\u4E2D\u8BF7\u7B49\u5F85\uFF1B\u542F\u52A8\u5931\u8D25\u65F6\u70B9\u201C\u67E5\u770B\u539F\u56E0\u201D\uFF0C\u6309\u63D0\u793A\u5904\u7406\u3002\u4EC5\u5728\u63D0\u4F9B\u201C\u542F\u52A8 AI \u5F15\u64CE\u201D\u6309\u94AE\u65F6\u624B\u52A8\u542F\u52A8\uFF1B\u82E5\u4ECD\u65E0\u6CD5\u4F7F\u7528\u63D2\u4EF6\uFF0C\u8BF7\u590D\u5236\u9519\u8BEF\u8BE6\u60C5\u8054\u7CFB\u7BA1\u7406\u5458\u6216\u63D2\u4EF6\u63D0\u4F9B\u65B9\u3002",
    "pluginOperationFailureGuidance.status": "\u5173\u95ED\u63D0\u793A\u540E\uFF0C\u91CD\u65B0\u8FDB\u5165\u5BF9\u5E94\u63D2\u4EF6\u5206\u7C7B\uFF0C\u6838\u5BF9\u7248\u672C\u3001\u5F00\u5173\u548C\u53EF\u7528\u72B6\u6001\u3002\u82E5\u4ECD\u65E0\u6CD5\u8BFB\u53D6\u6216\u4E0E\u672C\u6B21\u64CD\u4F5C\u4E0D\u7B26\uFF0C\u8BF7\u590D\u5236\u9519\u8BEF\u8BE6\u60C5\u8054\u7CFB\u7BA1\u7406\u5458\u6216\u63D2\u4EF6\u63D0\u4F9B\u65B9\uFF1B\u786E\u8BA4\u524D\u4E0D\u8981\u91CD\u590D\u63D0\u4EA4\u3002",
    "pluginOperationFailureGuidance.removal": "\u8BF7\u6309\u4E0A\u65B9\u5177\u4F53\u539F\u56E0\u5904\u7406\uFF1A\u5982\u63D0\u793A\u6587\u4EF6\u88AB\u5360\u7528\uFF0C\u5173\u95ED\u6B63\u5728\u4F7F\u7528\u8BE5\u63D2\u4EF6\u7684\u76F8\u5E94\u7A0B\u5E8F\uFF1B\u5982\u63D0\u793A\u65E0\u6743\u9650\uFF0C\u590D\u5236\u9519\u8BEF\u8BE6\u60C5\u8054\u7CFB\u7BA1\u7406\u5458\u3002\u82E5\u539F\u56E0\u6D89\u53CA AI \u5F15\u64CE\uFF0C\u67E5\u770B\u6807\u9898\u680F\u72B6\u6001\uFF0C\u542F\u52A8\u5931\u8D25\u65F6\u70B9\u201C\u67E5\u770B\u539F\u56E0\u201D\u3002\u5904\u7406\u540E\u6838\u5BF9\u63D2\u4EF6\u4ECD\u5728\u5217\u8868\u4E2D\uFF0C\u518D\u624B\u52A8\u5378\u8F7D\u3002",
    "pluginOperationFailureGuidance.removalRuntime": "\u63D2\u4EF6\u5DF2\u5378\u8F7D\uFF0C\u65E0\u9700\u518D\u6B21\u5378\u8F7D\u3002\u5173\u95ED\u63D0\u793A\u540E\uFF0C\u67E5\u770B\u6807\u9898\u680F\uFF08\u6700\u5C0F\u5316\u3001\u6700\u5927\u5316\u6309\u94AE\u65C1\uFF09\u7684 AI \u5F15\u64CE\u72B6\u6001\uFF1B\u542F\u52A8\u4E2D\u8BF7\u7B49\u5F85\uFF0C\u542F\u52A8\u5931\u8D25\u65F6\u70B9\u201C\u67E5\u770B\u539F\u56E0\u201D\u3002\u4EC5\u5728\u63D0\u4F9B\u201C\u542F\u52A8 AI \u5F15\u64CE\u201D\u6309\u94AE\u65F6\u624B\u52A8\u542F\u52A8\uFF1B\u82E5\u5F15\u64CE\u4ECD\u65E0\u6CD5\u5C31\u7EEA\uFF0C\u8BF7\u590D\u5236\u9519\u8BEF\u8BE6\u60C5\u8054\u7CFB\u7BA1\u7406\u5458\u6216\u63D2\u4EF6\u63D0\u4F9B\u65B9\u3002",
    "pluginOperationFailureGuidance.removalPolicy": "\u63D2\u4EF6\u5DF2\u5378\u8F7D\uFF0C\u65E0\u9700\u518D\u6B21\u5378\u8F7D\u3002\u8BF7\u590D\u5236\u9519\u8BEF\u8BE6\u60C5\uFF0C\u8054\u7CFB\u7BA1\u7406\u5458\u6838\u5BF9\u5378\u8F7D\u540E\u7684\u7F51\u7EDC\u7B56\u7565\u6216\u8FD0\u884C\u914D\u7F6E\u3002",
    "pluginOperationFailureGuidance.removalConfiguration": "\u63D2\u4EF6\u5DF2\u5378\u8F7D\uFF0C\u65E0\u9700\u518D\u6B21\u5378\u8F7D\u3002\u8BF7\u590D\u5236\u9519\u8BEF\u8BE6\u60C5\uFF0C\u8054\u7CFB\u7BA1\u7406\u5458\u6838\u5BF9\u5378\u8F7D\u540E\u7684\u63D2\u4EF6\u5141\u8BB8\u52A0\u8F7D\u5217\u8868\u53CA\u5269\u4F59\u914D\u7F6E\u3002",
